    String time();

    default String describe() {
        return "at " + time();
    }
}

interface Tagged {
    String tag();

    default String describe() {
        return "#" + tag();
    }
}

static class Event implements Timestamped, Tagged {
    private final String time;
    private final String tag;

    Event(String time, String tag) {
        this.time = time;
        this.tag = tag;
    }

    @Override
